//! Golden comparison of the manager command line against the Go binary
//! (fixtures generated by hack/golden/ctrlrt-cmd-flags/gen.sh).

use std::io::Write;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};

use ctrlrt_cmd::cmdline::ManagerFlags;
use ctrlrt_cmd::flag::{ErrorHandling, FlagError};

#[derive(Default)]
struct Buf(Vec<u8>);
impl Write for Buf {
    fn write(&mut self, b: &[u8]) -> std::io::Result<usize> {
        self.0.extend_from_slice(b);
        Ok(b.len())
    }
    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

fn fixtures() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/flags")
}

fn cases() -> Vec<String> {
    let mut v: Vec<String> = std::fs::read_dir(fixtures())
        .unwrap()
        .filter_map(|e| {
            let p = e.unwrap().path();
            (p.extension()? == "args")
                .then(|| p.file_stem().unwrap().to_string_lossy().into_owned())
        })
        .collect();
    v.sort();
    v
}

fn read(case: &str, ext: &str) -> String {
    std::fs::read_to_string(fixtures().join(format!("{case}.{ext}"))).unwrap()
}

fn args(case: &str) -> Vec<String> {
    read(case, "args").lines().map(str::to_string).collect()
}

#[test]
fn manager_flags_match_go_output() {
    let cases = cases();
    assert!(cases.len() >= 10);
    for case in cases {
        let buf = Arc::new(Mutex::new(Buf::default()));
        let b2 = buf.clone();
        let res = ManagerFlags::parse_from(
            "manager",
            ErrorHandling::ContinueOnError,
            args(&case),
            move |fs| fs.set_output(b2),
        );
        let code = match res {
            Ok(_) => 0,
            Err(FlagError::Help) => 0,
            Err(FlagError::Invalid(_)) => 2,
        };
        let out = String::from_utf8(buf.lock().unwrap().0.clone()).unwrap();
        assert_eq!(out, read(&case, "stderr"), "stderr of {case}");
        assert_eq!(read(&case, "stdout"), "", "{case}");
        assert_eq!(
            code.to_string(),
            read(&case, "exit").trim(),
            "exit code of {case}"
        );
    }
}

/// Runs in a child process: parses with ExitOnError (os.Exit semantics).
#[test]
fn exit_on_error_child() {
    let Ok(case) = std::env::var("CTRLRT_CMD_FLAGS_CASE") else {
        return;
    };
    let _ = ManagerFlags::parse_from("manager", ErrorHandling::ExitOnError, args(&case), |_| {});
    std::process::exit(0);
}

#[test]
fn exit_codes_and_stderr_match_go() {
    let exe = std::env::current_exe().unwrap();
    for case in cases() {
        let out = std::process::Command::new(&exe)
            .args([
                "exit_on_error_child",
                "--exact",
                "--nocapture",
                "--test-threads=1",
            ])
            .env("CTRLRT_CMD_FLAGS_CASE", &case)
            .output()
            .unwrap();
        assert_eq!(
            out.status.code().unwrap().to_string(),
            read(&case, "exit").trim(),
            "exit code of {case}"
        );
        let stderr = String::from_utf8_lossy(&out.stderr);
        assert!(
            stderr.contains(&read(&case, "stderr")),
            "stderr of {case}: {stderr}"
        );
    }
}
